import { ACCENTS, type AccentName } from './accent'

/*
 * The Antresol logo: two doors with a seam and bar pulls (the owner's icon, variant 5). In the app the tile and the pulls
 * take the accent's saturated colour, so they follow style and accent; the doors stay white. Installed (home-screen)
 * icons cannot change at runtime and keep the owner's #17181C (public/favicon.svg, generated by pwa-assets).
 */

export const LOGO_DOORS = '#FFFFFF'

/** The tile and pulls colour: the accent's `light` value in both themes (the dark pastels would not carry white doors). */
export function logoColor(accent: AccentName): string {
  return ACCENTS[accent].light
}

/** The logo as a standalone SVG document (the tab icon). Geometry: public/favicon.svg. */
export function logoSvg(color: string): string {
  return (
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">'
    + `<rect width="100" height="100" rx="24" fill="${color}"/>`
    + `<g fill="${LOGO_DOORS}"><rect x="14" y="28" width="35" height="44" rx="8"/><rect x="51" y="28" width="35" height="44" rx="8"/></g>`
    + `<g fill="${color}"><rect x="40" y="42" width="5" height="16" rx="2.5"/><rect x="55" y="42" width="5" height="16" rx="2.5"/></g>`
    + '</svg>'
  )
}

/** `href` for `<link rel="icon">`; the CSP's `img-src` allows data: URLs. */
export function faviconHref(color: string): string {
  return `data:image/svg+xml,${encodeURIComponent(logoSvg(color))}`
}
